<template><view class="queue-page" :class="{'scene-enter':visible}"><view class="heading"><button class="back" @click="back">‹</button><view><text class="ui-kicker">YOUR MEME WORKSHOP</text><text class="title">生成队列 <text v-if="unreadCount" class="unread-total">{{unreadCount}} 未查看</text></text></view><ui-icon name="queue" tone="accent" :size="52"/></view><view class="intro"><text>小窝继续做，你先去玩～</text><text>点开整行领取成品，左滑可删除。作品和再次制作所需素材保留近 7 天。</text></view><button v-if="!session" class="ui-secondary" @click="login" :loading="loggingIn">登录后，新作品可跨设备收好</button><button v-if="error" class="error" @click="refresh">{{error}} · 点击重试</button><view v-for="item in jobs" :key="item.id" class="swipe-row" :class="{'row-leaving':leaving===item.id}"><button v-if="!['queued','running'].includes(item.status)" class="swipe-delete" @click.stop="remove(item)"><ui-icon name="trash" tone="white" :size="36"/><text>删除</text></button><view class="job-card" :style="{transform:'translateX('+(opened===item.id?-86:0)+'px)'}" @click="openItem(item)" @touchstart="touchStart($event,item)" @touchmove="touchMove($event,item)" @touchend="touchEnd" @mousedown="touchStart($event,item)" @mousemove="touchMove($event,item)" @mouseup="touchEnd"><view class="job-cover"><image v-if="images[item.id]" :src="images[item.id]" mode="aspectFit"/><ui-icon v-else :name="item.status==='failed'?'image':'spark'" tone="accent" :size="52"/><view v-if="item.status==='completed' && !item.viewed && !item.viewedAt" class="unread-dot"/></view><view class="job-copy"><text class="job-title">{{item.kind==='livegif' && item.status==='completed'?'动图活起来啦':labels[item.status]||'正在制作'}}</text><text>{{item.message || '小窝已经接单啦'}}</text><text>{{formatTime(item.created_at)}}</text></view><view v-if="['queued','running'].includes(item.status)" class="working-ring"/><ui-icon v-else name="arrow" :size="30"/></view></view><view v-if="!jobs.length && !error" class="empty"><ui-icon name="image" :size="100" tone="accent"/><text>还没开工呢，去套个模板造梗吧。</text><button class="ui-primary" @click="goHome">去模板仓库</button></view><text v-if="jobs.length" class="swipe-tip">点整行看大图 · 左滑删除</text><preview-modal :show="!!activeItem" :is-generating="false" :image="activeImage" :allow-edit="false" :regeneratable="!!activeItem?.can_regenerate" @close="activeItem=null" @save="save" @share="share" @regenerate="again"/><bottom-tabs active="my"/></view></template>
<script setup>
import {ref,computed,watch} from 'vue'
import {onShow,onHide,onUnload} from '@dcloudio/uni-app'
import {useLibrary} from '@/composables/useLibrary'
import {listStudioJobs,privateImage,deleteStudioJob,guestResults,removeGuestMeme,unreadCount,refreshUnread,viewStudioJob,regenerateStudioJob} from '@/services/studioService'
import {shareOriginalImage} from '@/services/wechatSharing'
import BottomTabs from '@/components/BottomTabs.vue'
import PreviewModal from '@/components/PreviewModal.vue'
import UiIcon from '@/components/UiIcon.vue'
const {session,loggingIn,loginWeChat}=useLibrary(),jobs=ref([]),images=ref({}),error=ref(''),visible=ref(false),activeItem=ref(null),opened=ref(''),leaving=ref('')
const activeImage=computed(()=>images.value[activeItem.value?.id]||'')
let timer,loading=false,epoch=0,gesture=null,lastSwipe=null
watch(()=>session.value?.profile?.id,()=>{epoch++;jobs.value=[];images.value={};activeItem.value=null;opened.value='';error.value='';refreshUnread();if(visible.value)refresh()})
const labels={queued:'排队等魔法',running:'正在认真造梗',completed:'损图出炉啦',failed:'这次没出炉'}
const refresh=async()=>{if(!session.value){jobs.value=guestResults();images.value=Object.fromEntries(jobs.value.map(j=>[j.id,j.localPath]));refreshUnread();return}if(loading)return;loading=true;const owner=session.value.profile.id,request=epoch;try{const all=await listStudioJobs();if(owner!==session.value?.profile?.id||request!==epoch)return;const local=guestResults().filter(item=>item.status==='completed'||!all.some(job=>job.id===item.serverId));jobs.value=[...local,...all.filter(j=>['manual','livegif'].includes(j.kind)&&!local.some(item=>item.serverId===j.id))].sort((a,b)=>b.created_at-a.created_at);for(const item of local)images.value[item.id]=item.localPath;error.value='';refreshUnread();for(const j of jobs.value.filter(j=>j.result_url&&!images.value[j.id]).slice(0,20)){try{const path=await privateImage(j.result_url);if(request===epoch&&owner===session.value?.profile?.id)images.value[j.id]=path}catch(_){}}}catch(e){if(request===epoch&&owner===session.value?.profile?.id){error.value=e.message;jobs.value=guestResults();for(const item of jobs.value)images.value[item.id]=item.localPath}}finally{loading=false}}
const login=async()=>{try{await loginWeChat();refresh()}catch(e){error.value=e.message}}
const openItem=async item=>{if(lastSwipe?.id===item.id && Date.now()-lastSwipe.time<300)return;if(opened.value){opened.value='';return}if(item.status!=='completed'){uni.showToast({title:item.message||'还在认真制作中',icon:'none'});return}const owner=session.value?.profile?.id;try{if(!images.value[item.id]){const path=await privateImage(item.result_url);if(owner!==session.value?.profile?.id)return;images.value[item.id]=path}activeItem.value=item;await viewStudioJob(item);item.viewed=true;item.viewedAt=Date.now()}catch(e){error.value=e.message}}
const save=async()=>{if(!activeImage.value)return;try{if(typeof document!=='undefined'){const a=document.createElement('a');a.href=activeImage.value;a.download='GenSticker'+(activeItem.value?.kind==='livegif'?'.gif':'.png');a.click();return}await uni.saveImageToPhotosAlbum({filePath:activeImage.value});uni.showToast({title:'已保存',icon:'success'})}catch(e){error.value='请在设置中允许保存到相册'}}
const share=()=>shareOriginalImage(activeImage.value,title=>uni.showToast({title,icon:'none'}))
const again=async()=>{const item=activeItem.value;if(!item?.can_regenerate)return;try{await regenerateStudioJob(item.id);activeItem.value=null;uni.showToast({title:'重新开工啦，小窝继续做～',icon:'none'});await refresh()}catch(e){error.value=e.message}}
const touchStart=(e,item)=>{const p=e.touches?.[0]||e;gesture={id:item.id,x:p.clientX,y:p.clientY}}
const touchMove=(e,item)=>{if(!gesture||gesture.id!==item.id||(!e.touches&&!e.buttons)||['queued','running'].includes(item.status))return;const p=e.touches?.[0]||e,dx=p.clientX-gesture.x,dy=p.clientY-gesture.y;if(Math.abs(dx)>35&&Math.abs(dx)>Math.abs(dy)*1.4){opened.value=dx<0?item.id:'';lastSwipe={id:item.id,time:Date.now()}}}
const touchEnd=()=>{gesture=null}
const remove=async item=>{if(leaving.value)return;leaving.value=item.id;try{if(item.local||item.localPath)removeGuestMeme(item.id);else{await deleteStudioJob(item.id);removeGuestMeme(item.id)}await new Promise(resolve=>setTimeout(resolve,180));jobs.value=jobs.value.filter(j=>j.id!==item.id);delete images.value[item.id];opened.value='';refreshUnread()}catch(e){error.value=e.message}finally{leaving.value=''}}
const formatTime=t=>new Date(t*1000).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})
const goHome=()=>uni.switchTab({url:'/pages/index/index'}),back=()=>getCurrentPages().length>1?uni.navigateBack():goHome()
onShow(()=>{visible.value=true;epoch++;refresh();timer=setInterval(()=>{if(visible.value)refresh()},5000)})
const stop=()=>{visible.value=false;epoch++;clearInterval(timer)};onHide(stop);onUnload(stop)
</script>
<style scoped>
.queue-page{min-height:100vh;background:var(--paper);padding:calc(110rpx + env(safe-area-inset-top)) 28rpx calc(160rpx + env(safe-area-inset-bottom))}.heading{display:flex;align-items:center;gap:20rpx;margin-bottom:28rpx}.heading>view{flex:1}.back{font-size:56rpx;width:60rpx;color:var(--ink)}.title{display:block;font-size:37rpx;font-weight:800}.unread-total{font-size:20rpx;color:#fff;background:#ee6a58;padding:3rpx 12rpx;border-radius:20rpx;vertical-align:middle;margin-left:8rpx}.intro{background:#f6ecd9;border:3rpx solid white;border-radius:30rpx;padding:28rpx;margin-bottom:30rpx}.intro text{display:block;font-size:23rpx;line-height:1.8;color:#968972}.intro text:first-child{font-weight:700;font-size:29rpx;color:var(--ink);margin-bottom:8rpx}.swipe-row{position:relative;margin-bottom:22rpx;border-radius:28rpx;background:#ed7e65;overflow:hidden;box-shadow:0 6rpx 0 #efe5da;transition:opacity .2s,transform .2s}.swipe-delete{position:absolute;right:0;top:0;bottom:0;width:86px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:10rpx;font-size:24rpx;color:white}.job-card{position:relative;display:flex;align-items:center;gap:18rpx;padding:24rpx;background:white;border-radius:28rpx;transition:transform .22s cubic-bezier(.2,.8,.2,1);touch-action:pan-y}.job-cover{width:112rpx;height:112rpx;border-radius:22rpx;flex-shrink:0;background:#fff2da;position:relative;display:flex;align-items:center;justify-content:center}.job-cover image{width:100%;height:100%;border-radius:22rpx}.unread-dot{position:absolute;right:-6rpx;top:-6rpx;width:20rpx;height:20rpx;background:#ef6658;border:4rpx solid white;border-radius:50%;animation:ui-pop .3s ease-out}.job-copy{flex:1;min-width:0}.job-copy text{display:block;font-size:21rpx;color:#a29a89;line-height:1.7}.job-copy .job-title{font-weight:700;font-size:28rpx;color:var(--ink)}.working-ring{width:30rpx;height:30rpx;border:3rpx solid #f5dac0;border-top-color:#e68e62;border-radius:50%;animation:ui-spin .9s linear infinite}.row-leaving{transform:translateX(-100%);opacity:0}.empty{display:flex;align-items:center;flex-direction:column;gap:30rpx;text-align:center;padding:60rpx 25rpx;color:#9d9788;font-size:24rpx}.empty button{width:100%}.error{width:100%;background:#fff0e5;color:#b36f52;border-radius:20rpx;font-size:23rpx;padding:20rpx;margin:18rpx 0}.swipe-tip{display:block;text-align:center;color:#b3a48f;font-size:21rpx;margin-top:25rpx}
</style>
